public sealed class ConnectionId : IEquatable<ConnectionId>
{
    private readonly string _value;
    private ConnectionId(string value) => _value = value;   // factory only
    public static ConnectionId Parse(string s) => new ConnectionId(s);
    public bool Equals(ConnectionId? other) => other is not null && _value == other._value;
